### 1. `internal/webui/frontend/src/components/CreateWorkspaceModal/CreateWorkspaceModal.tsx`

**Change:** Restructure `handleSubmit` (lines 111-189) to separate API error handling from callback error handling.

Current code (lines 154-175):
```typescript
try {
  const data = await createWorkspace(req);
  onSuccess(data, req.name);
  onClose();
} catch (err: unknown) {
  const message = err instanceof Error ? err.message : "Failed to create workspace";
  if (...) {
    setError((err as ...).body.error);
  } else {
    setError(message);
  }
} finally {
  setIsSubmitting(false);
}
