### `internal/webui/analytics_types.go`

Contains these types:

```go
package webui

import "time"

// --- Response envelope ---

// AnalyticsResponse is the JSON envelope for GET /api/analytics.
type AnalyticsResponse struct {
    Success bool            `json:"success"`
    Data    *AnalyticsData  `json:"data,omitempty"`
    Error   string          `json:"error,omitempty"`
}

// AnalyticsData holds all computed analytics series for the requested time range.
type AnalyticsData struct {
    // Query metadata
    RangeStart time.Time `json:"range_start"`
    RangeEnd   time.Time `json:"range_end"`

    // Summary statistics (6 cards: opened, closed, avg cycle, avg lead, total cost, total sessions)
    Summary AnalyticsSummary `json:"summary"`

    // Time-series data
    Burndown   []BurndownPoint   `json:"burndown"`
    Throughput []ThroughputPoint `json:"throughput"`

    // Distribution histograms
    CycleTime []HistogramBucket `json:"cycle_time"`
    LeadTime  []HistogramBucket `json:"lead_time"`

    // Per-task cost breakdown
    CostRows []CostRow `json:"cost_rows"`
}

// --- Summary ---

// AnalyticsSummary provides the six headline stats for the SummaryBar component.
type AnalyticsSummary struct {
    Opened       int     `json:"opened"`         // Issues opened in range
    Closed       int     `json:"closed"`         // Issues closed in range
    AvgCycleDays float64 `json:"avg_cycle_days"` // Average cycle time (in_progress → closed) in days
    AvgLeadDays  float64 `json:"avg_lead_days"`  // Average lead time (created → closed) in days
    TotalCostUSD float64 `json:"total_cost_usd"` // Sum of session costs in range
    SessionCount int     `json:"session_count"`  // Number of sessions in range
}

// --- Burndown ---

// BurndownPoint represents one date bucket in the burndown chart.
// The BurndownChart component renders opened/closed as Line series.
type BurndownPoint struct {
    Date   string `json:"date"`   // "YYYY-MM-DD"
    Opened int    `json:"opened"` // Issues opened on this date
    Closed int    `json:"closed"` // Issues closed on this date
}

// --- Throughput ---

// ThroughputPoint represents one date bucket in the throughput chart.
// Breakdown maps allow the frontend groupBy selector (type/priority/assignee).
type ThroughputPoint struct {
    Date       string         `json:"date"`                  // "YYYY-MM-DD"
    Total      int            `json:"total"`                 // Total issues closed
    ByType     map[string]int `json:"by_type,omitempty"`     // e.g. {"task":3,"bug":1}
    ByPriority map[string]int `json:"by_priority,omitempty"` // e.g. {"P0":1,"P2":2}
    ByAssignee map[string]int `json:"by_assignee,omitempty"` // e.g. {"alice":2,"bob":1}
}

// --- Histograms ---

// HistogramBucket represents one bucket in a cycle-time or lead-time histogram.
// The bucket label describes the range (e.g., "0-1d", "1-3d", "3-7d").
type HistogramBucket struct {
    Label    string  `json:"label"`     // Human-readable range label
    MinDays  float64 `json:"min_days"`  // Lower bound in days (inclusive)
    MaxDays  float64 `json:"max_days"`  // Upper bound in days (exclusive)
    Count    int     `json:"count"`     // Number of issues in this bucket
}

// --- Cost ---

// CostRow represents one row in the cost table, aggregated per task.
type CostRow struct {
    TaskID        string  `json:"task_id"`
    TaskTitle     string  `json:"task_title"`
    SessionCount  int     `json:"session_count"`
    TotalTokens   int64   `json:"total_tokens"`    // input + output
    InputTokens   int64   `json:"input_tokens"`
    OutputTokens  int64   `json:"output_tokens"`
    DurationSec   float64 `json:"duration_sec"`     // Total session duration
    CostUSD       float64 `json:"cost_usd"`
}
```

