      if (!options?.loomServerAvailable && options?.loomServerAvailable !== undefined) {
        // Simulate loom unavailable: return invalid JSON
        await route.fulfill({ status: 200, contentType: "application/json", body: "invalid json{" });
        return;
      }
      if (url.includes("/api/loom/api/agents")) {
        const agents = options?.emptyAgents ? [] : mockAgents;
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify({ agents, timestamp: "2026-01-24T12:00:00Z" }),
        });
      } else if (url.includes("/api/loom/api/status")) {
        const status = options?.emptyAgents
          ? { ...mockLoomStatus, agents: [], agent_tasks: {} }
          : mockLoomStatus;
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(status),
        });
      } else if (url.includes("/api/loom/api/tasks")) {
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(mockLoomTasks),
        });
      } else if (url.includes("/health")) {
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify({ status: "ok" }),
        });
      } else {
        // Default: return empty data for unhandled loom endpoints
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify({}),
        });
      }
    });
    ```

