```typescript
async function navigateAndWait(page: Page) {
  await page.goto("/ws/default/", { waitUntil: "domcontentloaded" });
  // Wait for workspace data to load — sidebar renders after this
  await page.waitForResponse(
    (res) => res.url().includes("/api/workspaces/active") && res.status() === 200,
    { timeout: 10000 },
  );
}
