**Setup helpers:**

\`\`\`typescript
interface SetupOptions {
  transcriptDelay?: number;    // ms delay before transcript response
  diffDelay?: number;          // ms delay before diff response
  emptyTranscript?: boolean;   // return empty entries array
  diff404?: boolean;           // return 404 for diff endpoint
  transcriptError?: boolean;   // return 500 for transcript endpoint
  diffError?: boolean;         // return 500 for diff endpoint
}

async function setupMocks(page: Page, options?: SetupOptions) {
  // 1. SSE mock — MUST be set up before navigation
  const sse = createSSEMock(page);
  await sse.connect();

  // 2. Auth mock — prevent auth token fetch failures
  await page.route('**/api/auth/token', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ token: 'test-token-e2e' }),
    });
  });

  // 3. Health/stats/blocked — prevent console errors
  await page.route('**/api/health', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ status: 'ok', daemon: true }),
    });
  });
  await page.route('**/api/stats', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ success: true, data: { open: 1, in_progress: 0, review: 0, blocked: 0, closed: 0 } }),
    });
  });
  await page.route('**/api/blocked', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ success: true, data: [] }),
    });
  });

  // 4. /api/ready — return our test issue
  await page.route('**/api/ready', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ success: true, data: [MOCK_ISSUE] }),
    });
  });

  // 5. /api/issues/{id} — return issue details (unwrapped, per comments-section.spec.ts pattern)
  await page.route('**/api/issues/*', async (route) => {
    if (route.request().method() !== 'GET') { await route.fallback(); return; }
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ ...MOCK_ISSUE, dependencies: [], dependents: [] }),
    });
  });

  // --- Session endpoints (register list FIRST, specific sub-paths AFTER for LIFO priority) ---

  // 6. /api/tasks/{id}/sessions — session list
  await page.route('**/api/tasks/*/sessions', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ success: true, data: { task_id: MOCK_ISSUE.id, sessions: MOCK_SESSIONS } }),
    });
  });

  // 7. /api/tasks/{id}/sessions/{sid}/transcript — JSON with {success, data: {session_id, entries}}
  await page.route('**/api/tasks/*/sessions/*/transcript', async (route) => {
    if (options?.transcriptError) {
      await route.fulfill({ status: 500, contentType: 'application/json', body: JSON.stringify({ error: 'Internal error' }) });
      return;
    }
    if (options?.transcriptDelay) {
      await new Promise(r => setTimeout(r, options.transcriptDelay));
    }
    const entries = options?.emptyTranscript ? [] : MOCK_TRANSCRIPT;
    const sessionId = route.request().url().match(/sessions\/([^/]+)\/transcript/)?.[1] ?? 'unknown';
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ success: true, data: { session_id: sessionId, entries } }),
    });
  });

  // 8. /api/tasks/{id}/sessions/{sid}/diff — raw text/plain (NOT JSON)
  await page.route('**/api/tasks/*/sessions/*/diff', async (route) => {
    if (options?.diff404) {
      await route.fulfill({ status: 404, contentType: 'application/json', body: JSON.stringify({ error: 'Not found' }) });
      return;
    }
    if (options?.diffError) {
      await route.fulfill({ status: 500, contentType: 'application/json', body: JSON.stringify({ error: 'Internal error' }) });
      return;
    }
    if (options?.diffDelay) {
      await new Promise(r => setTimeout(r, options.diffDelay));
    }
    await route.fulfill({
      status: 200,
      contentType: 'text/plain',
      body: MOCK_DIFF,
    });
  });

  return { sse };
}
