// ============= REACTION OPERATIONS =============

/**
 * Request body for reaction operations.
 */
export interface ReactionRequest {
  emoji: string;
}

/**
 * Add a reaction to a comment.
 */
export async function addReaction(
  workspaceId: string,
  issueId: string,
  commentId: number,
  emoji: string,
): Promise<CommentReaction> {
  const response = await post<ApiResult<CommentReaction>>(
    wsUrl(
      workspaceId,
      `/issues/${encodeURIComponent(issueId)}/comments/${commentId}/reactions`,
    ),
    { emoji },
  );
  return unwrap(response);
}

/**
 * Remove a reaction from a comment.
 * Uses DELETE with body because emoji characters are problematic in URLs.
 */
export async function removeReaction(
  workspaceId: string,
  issueId: string,
  commentId: number,
  emoji: string,
): Promise<void> {
  const response = await delWithBody<ApiResult<null>>(
    wsUrl(
      workspaceId,
      `/issues/${encodeURIComponent(issueId)}/comments/${commentId}/reactions`,
    ),
    { emoji },
  );
  unwrap(response);
}

// ============= MENTION OPERATIONS =============

/**
 * Fetch mention suggestions for an issue.
 * Returns unique names from assignees and comment authors.
 */
export async function fetchMentionSuggestions(
  workspaceId: string,
  issueId: string,
): Promise<MentionSuggestion[]> {
  const response = await get<ApiResult<MentionSuggestion[]>>(
    wsUrl(
      workspaceId,
      `/issues/${encodeURIComponent(issueId)}/mentions`,
    ),
  );
  return unwrap(response);
}
