**Props interface:**

```typescript
export interface ReactionPickerProps {
  /** Whether the picker popover is visible */
  isOpen: boolean;
  /** Called when the user selects an emoji. Parent handles the API call. */
  onSelect: (emoji: string) => void;
  /** Called when the picker should close (Escape, click-outside, or after selection) */
  onClose: () => void;
  /** Additional CSS class name for the container */
