**Rendering:**

\`\`\`tsx
export function MentionDropdown({
  isOpen,
  suggestions,
  focusedIndex,
  onSelect,
  onClose,
  style,
  className,
}: MentionDropdownProps): JSX.Element | null {
  const containerRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  // Click-outside handler
  useEffect(() => {
    if (!isOpen) return;
    const handleMouseDown = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    document.addEventListener("mousedown", handleMouseDown);
    return () => document.removeEventListener("mousedown", handleMouseDown);
  }, [isOpen, onClose]);

  // Scroll focused item into view
  useEffect(() => {
    if (focusedIndex >= 0 && listRef.current) {
      const items = listRef.current.querySelectorAll("[data-testid^='mention-dropdown-item-']");
      items[focusedIndex]?.scrollIntoView({ block: "nearest" });
    }
  }, [focusedIndex]);

  if (!isOpen) return null;

  const rootClassName = [styles.mentionDropdown, className].filter(Boolean).join(" ");

  return (
    <div ref={containerRef} className={rootClassName} style={style}>
      {suggestions.length > 0 ? (
        <ul
          ref={listRef}
          className={styles.list}
          role="listbox"
          aria-label="Mention suggestions"
          data-testid="mention-dropdown-list"
        >
          {suggestions.map((suggestion, index) => (
            <li
              key={suggestion.name}
              className={styles.item}
              role="option"
              aria-selected={index === focusedIndex}
              data-focused={index === focusedIndex || undefined}
              onClick={() => onSelect(suggestion.name)}
              data-testid={\`mention-dropdown-item-\${suggestion.name}\`}
            >
              <span className={styles.atSymbol}>@</span>
              <span className={styles.name}>{suggestion.name}</span>
            </li>
          ))}
        </ul>
      ) : (
        <div
          className={styles.noResults}
          data-testid="mention-dropdown-no-results"
        >
          No matches
        </div>
      )}
    </div>
  );
}
\`\`\`

