**Caret coordinate utility** (module-level function above the component):
```typescript
function getCaretCoordinates(
  textarea: HTMLTextAreaElement,
  position: number,
): { top: number; left: number } {
  const mirror = document.createElement("div");
  const computed = getComputedStyle(textarea);
  mirror.style.cssText = [
    "position:absolute", "visibility:hidden", "white-space:pre-wrap",
    "word-wrap:break-word", "overflow:hidden",
    `width:${computed.width}`, `font:${computed.font}`,
    `padding:${computed.padding}`, `border:${computed.border}`,
    `line-height:${computed.lineHeight}`, `letter-spacing:${computed.letterSpacing}`,
  ].join(";");
  const textBefore = textarea.value.substring(0, position);
  mirror.appendChild(document.createTextNode(textBefore));
  const span = document.createElement("span");
  span.textContent = "\u200b";
  mirror.appendChild(span);
  document.body.appendChild(mirror);
  const top = span.offsetTop - textarea.scrollTop;
  const left = span.offsetLeft;
  document.body.removeChild(mirror);
  const lineHeight = parseInt(computed.lineHeight) || 20;
  return { top: top + lineHeight, left };
}
```

**Mention trigger detection** (called from handleTextChange):
```typescript
function detectMentionTrigger(value: string, cursorPos: number): { triggerPos: number; query: string } | null {
  // Scan backwards from cursor for @
  let i = cursorPos - 1;
  while (i >= 0) {
    const ch = value[i];
    if (ch === "@") {
      // @ must be at start or preceded by whitespace
      if (i === 0 || /\s/.test(value[i - 1])) {
        return { triggerPos: i, query: value.substring(i + 1, cursorPos) };
      }
      return null; // @ preceded by non-whitespace (e.g., email)
    }
    if (/\s/.test(ch)) return null; // hit whitespace before finding @
    i--;
  }
  return null;
}
```

