const handleTextChange = useCallback(
  (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newValue = e.target.value;
    const cursorPos = e.target.selectionStart;
    setText(newValue);
    if (error) setError(null);

    const trigger = detectMentionTrigger(newValue, cursorPos);
    if (trigger) {
      setMentionOpen(true);
      setMentionQuery(trigger.query);
      setMentionTriggerPos(trigger.triggerPos);

      // Compute dropdown position
      if (textareaRef.current) {
        const coords = getCaretCoordinates(textareaRef.current, cursorPos);
        setMentionDropdownStyle({ top: coords.top, left: coords.left });
      }

      // Fetch suggestions once per dropdown session
      if (!mentionFetchedRef.current) {
        mentionFetchedRef.current = true;
        fetchMentionSuggestions(workspaceId, issueId)
          .then(setMentionSuggestions)
          .catch(() => setMentionSuggestions([]));
      }
    } else {
      if (mentionOpen) {
        setMentionOpen(false);
        setMentionQuery("");
        setMentionTriggerPos(-1);
        mentionFetchedRef.current = false;
      }
    }
  },
  [error, workspaceId, issueId, mentionOpen],
);
```

