const handleMentionSelect = useCallback(
  (name: string) => {
    if (mentionTriggerPos < 0 || !textareaRef.current) return;
    const before = text.substring(0, mentionTriggerPos);
    const after = text.substring(textareaRef.current.selectionStart);
    const inserted = `@${name} `;
    const newText = before + inserted + after;
    setText(newText);
    setMentionOpen(false);
    setMentionQuery("");
    setMentionTriggerPos(-1);
    mentionFetchedRef.current = false;

    // Reposition cursor after inserted text
    const newCursorPos = mentionTriggerPos + inserted.length;
    requestAnimationFrame(() => {
      if (textareaRef.current) {
        textareaRef.current.selectionStart = newCursorPos;
        textareaRef.current.selectionEnd = newCursorPos;
        textareaRef.current.focus();
      }
    });
  },
  [text, mentionTriggerPos],
);
```

