import { test, expect } from '../fixtures/base';
import type { Page } from '@playwright/test';

// Helper: inject mock WebSocket via addInitScript
async function injectMockWebSocket(page: Page) {
  await page.addInitScript(() => {
    const instances: any[] = [];
    class MockWebSocket {
      url: string;
      readyState = 0; // CONNECTING
      binaryType = 'blob';
      onopen: ((ev: Event) => void) | null = null;
      onclose: ((ev: CloseEvent) => void) | null = null;
      onmessage: ((ev: MessageEvent) => void) | null = null;
      onerror: ((ev: Event) => void) | null = null;

      static CONNECTING = 0;
      static OPEN = 1;
      static CLOSING = 2;
      static CLOSED = 3;

      constructor(url: string) {
        this.url = url;
        instances.push(this);
        // Fire onopen asynchronously to simulate connection
        setTimeout(() => {
          this.readyState = 1; // OPEN
          this.onopen?.(new Event('open'));
        }, 0);
      }
      send() {}
      close(code?: number) {
        this.readyState = 3; // CLOSED
        this.onclose?.(new CloseEvent('close', { code: code ?? 1000 }));
      }
      addEventListener() {}
      removeEventListener() {}
      dispatchEvent() { return true; }
    }
    // Preserve constants
    Object.defineProperty(MockWebSocket, 'CONNECTING', { value: 0 });
    Object.defineProperty(MockWebSocket, 'OPEN', { value: 1 });
    Object.defineProperty(MockWebSocket, 'CLOSING', { value: 2 });
    Object.defineProperty(MockWebSocket, 'CLOSED', { value: 3 });

    (window as any).WebSocket = MockWebSocket;
    (window as any).__mockWSInstances = instances;
  });
}

