**Change 1: Add per-session rate limit middleware for token endpoint.**
Add before the Better Auth handler mount (after CORS middleware, per task .10's middleware ordering):

```typescript
import { env } from "./lib/env.js";
import { logger } from "./lib/logger.js";

// Per-session rate limit on POST /api/auth/token: 10 req/min per session
// Prevents token stockpiling from a compromised session
const tokenRateLimit = new Map<string, { count: number; resetAt: number }>();

app.use("/api/auth/token", async (c, next) => {
  if (c.req.method !== "POST") {
    return next();
  }

  // Extract session identifier from cookie
  const cookies = c.req.header("cookie") ?? "";
  const sessionMatch = cookies.match(/better-auth\.session_token=([^;]+)/);
  const sessionKey = sessionMatch?.[1] ?? c.req.header("x-forwarded-for") ?? "unknown";

  const now = Date.now();
  const window = 60_000; // 1 minute
  const maxRequests = 10;

  let entry = tokenRateLimit.get(sessionKey);
  if (!entry || now >= entry.resetAt) {
    entry = { count: 0, resetAt: now + window };
    tokenRateLimit.set(sessionKey, entry);
  }

  entry.count++;
  if (entry.count > maxRequests) {
    logger.warn("token endpoint rate limited", { sessionKey: sessionKey.slice(0, 8) + "..." });
    return c.json({ error: "rate limit exceeded" }, 429);
  }

  // Periodically clean stale entries (every 100 requests)
  if (tokenRateLimit.size > 1000) {
    for (const [key, val] of tokenRateLimit) {
      if (now >= val.resetAt) tokenRateLimit.delete(key);
    }
  }

  return next();
});
```

**Change 2: Add Cache-Control: no-store on token endpoint response.**
Add after the Better Auth handler mount:

```typescript
// Ensure Cache-Control: no-store on token endpoint responses
// Prevents browser/proxy caching of JWTs
app.use("/api/auth/token", async (c, next) => {
  await next();
  if (c.req.method === "POST") {
    c.header("Cache-Control", "no-store");
    c.header("Pragma", "no-cache");
  }
});
```

**Important ordering note:** The Cache-Control middleware must run AFTER the auth handler sets the response body, so it should be a post-processing middleware (uses `await next()` then modifies headers). However, Hono processes middleware in order — the `await next()` pattern naturally handles this. Place this middleware AFTER the auth handler mount in the source file, but it will execute as a response modifier.

**Alternative approach:** If Hono's middleware ordering makes post-processing tricky, implement as a single middleware BEFORE the auth handler:

```typescript
app.use("/api/auth/token", async (c, next) => {
  // Rate limit (pre-processing)
  if (c.req.method === "POST") {
    // ... rate limit logic ...
  }
  await next();
  // Cache headers (post-processing)
  if (c.req.method === "POST") {
    c.header("Cache-Control", "no-store");
    c.header("Pragma", "no-cache");
  }
});
```

This combined approach is cleaner and avoids ordering ambiguity. The implementer should test both approaches and pick whichever works correctly with Hono's middleware execution model.

