  entry: FileEntry,
  filter: string,
  treeData: Map<string, FileEntry[]>,
): boolean {
  if (!filter) return true;
  if (entry.name.toLowerCase().includes(filter.toLowerCase())) return true;
  if (entry.isDir) {
    const children = treeData.get(entry.path);
    if (children) {
      return children.some((child) => shouldShow(child, filter, treeData));
    }
  }
  return false;
}

function TreeNode({ entry, depth, treeData, expanded, selectedPath, filterText, onToggle, onSelectFile }: TreeNodeProps) {
  const isExpanded = expanded.has(entry.path);
  const isSelected = selectedPath === entry.path;
  const children = entry.isDir ? treeData.get(entry.path) : undefined;
  const indent = depth * 16;

  const handleClick = useCallback(() => {
    if (entry.isDir) {
      onToggle(entry.path);
    } else {
      onSelectFile(entry.path);
    }
  }, [entry, onToggle, onSelectFile]);

  return (
    <>
      <button
        type="button"
        className={styles.treeNode}
        style={{ paddingLeft: indent }}
        data-selected={isSelected || undefined}
        data-dir={entry.isDir || undefined}
        onClick={handleClick}
        aria-expanded={entry.isDir ? isExpanded : undefined}
        aria-label={entry.name}
      >
        {entry.isDir ? (
          <span className={`${styles.chevron} ${isExpanded ? styles.chevronExpanded : ""}`}>
            {/* Right-pointing triangle SVG */}
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M6 4l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="1.5" />
            </svg>
          </span>
        ) : (
          <span className={styles.fileIconSpacer} />
        )}
        <span className={styles.icon}>
          {entry.isDir ? (
            /* Folder SVG icon */
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M2 3h4l2 2h6v8H2V3z" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
            </svg>
          ) : (
            /* File SVG icon */
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M4 2h5l3 3v9H4V2z" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
              <path d="M9 2v3h3" fill="none" stroke="currentColor" strokeWidth="1.2" />
            </svg>
          )}
        </span>
        <span className={styles.fileName}>
          {highlightMatch(entry.name, filterText)}
        </span>
      </button>
      {entry.isDir && isExpanded && children && (
        children
          .filter((child) => shouldShow(child, filterText, treeData))
          .map((child) => (
            <TreeNode
              key={child.path}
              entry={child}
              depth={depth + 1}
              treeData={treeData}
              expanded={expanded}
              selectedPath={selectedPath}
              filterText={filterText}
              onToggle={onToggle}
              onSelectFile={onSelectFile}
            />
          ))
      )}
    </>
  );
}

export function FileTree({ treeData, expanded, selectedPath, filterText, onToggle, onSelectFile }: FileTreeProps) {
  const rootEntries = treeData.get("") ?? [];

  return (
    <div className={styles.tree} role="tree" aria-label="File tree">
      {rootEntries
        .filter((entry) => shouldShow(entry, filterText, treeData))
        .map((entry) => (
          <TreeNode
            key={entry.path}
            entry={entry}
            depth={0}
            treeData={treeData}
            expanded={expanded}
            selectedPath={selectedPath}
            filterText={filterText}
            onToggle={onToggle}
            onSelectFile={onSelectFile}
          />
        ))}
      {rootEntries.length === 0 && !filterText && (
        <div className={styles.empty}>No files found</div>
      )}
      {rootEntries.length > 0 && filterText && rootEntries.filter((e) => shouldShow(e, filterText, treeData)).length === 0 && (
        <div className={styles.empty}>No matches for &ldquo;{filterText}&rdquo;</div>
      )}
    </div>
  );
}
```

### 3. `internal/webui/frontend/src/components/FileExplorer/FileViewer.tsx`

Slide-out panel for displaying file content (~80-100 lines). Structure:

```typescript
import { useMemo, lazy, Suspense } from "react";
import type { FileReadData } from "@/api/files";
import styles from "./FileExplorer.module.css";

// Lazy load CodeMirrorEditor to keep CM6 out of main bundle
const CodeMirrorEditor = lazy(() =>
  import("@/components/CodeMirrorEditor").then((m) => ({ default: m.CodeMirrorEditor })),
);

interface FileViewerProps {
  isOpen: boolean;
  path: string | null;
  fileData: FileReadData | null;
  isLoading: boolean;
  error: string | null;
  onClose: () => void;
}

// Map file extension to CM6 language string
function detectLanguage(path: string): string | undefined {
  const ext = path.split(".").pop()?.toLowerCase();
  switch (ext) {
    case "go": return "go";
    case "json": return "json";
    case "yaml": case "yml": return "yaml";
    case "md": case "markdown": return "markdown";
    default: return undefined;
  }
}

export function FileViewer({ isOpen, path, fileData, isLoading, error, onClose }: FileViewerProps) {
  const language = useMemo(() => (path ? detectLanguage(path) : undefined), [path]);
  const fileName = useMemo(() => (path ? path.split("/").pop() ?? path : ""), [path]);

  const overlayClassName = [styles.overlay, isOpen ? styles.overlayOpen : ""].filter(Boolean).join(" ");

  return (
    <div className={overlayClassName} onClick={onClose} aria-hidden={!isOpen}>
      <div className={styles.viewerPanel} onClick={(e) => e.stopPropagation()} role="dialog" aria-label={`File: ${fileName}`}>
        <div className={styles.viewerHeader}>
          <span className={styles.viewerPath} title={path ?? ""}>{path}</span>
          <button type="button" className={styles.closeButton} onClick={onClose} aria-label="Close file viewer">
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.5" />
            </svg>
          </button>
        </div>
        <div className={styles.viewerContent}>
          {isLoading && <div className={styles.loading}>Loading file...</div>}
          {error && <div className={styles.error}>{error}</div>}
          {fileData && fileData.binary && (
            <div className={styles.binaryNotice}>Binary file — cannot display</div>
          )}
          {fileData && !fileData.binary && (
            <Suspense fallback={<div className={styles.loading}>Loading editor...</div>}>
              <CodeMirrorEditor
                value={fileData.content}
                language={language}
                readOnly={true}
              />
            </Suspense>
          )}
        </div>
      </div>
    </div>
  );
}
```

