**Add `lockIndex` helper** (new method on Store):
```go
// lockIndex acquires an exclusive advisory lock via index.lock.
// The caller MUST call lockfile.FlockUnlock(f) and f.Close() when done.
func (s *Store) lockIndex() (*os.File, error) {
    lockPath := filepath.Join(s.dir, "index.lock")
    f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDONLY, 0o600)
    if err != nil {
        return nil, fmt.Errorf("open index lock: %w", err)
    }
    if err := lockfile.FlockExclusiveBlocking(f); err != nil {
        f.Close()
        return nil, fmt.Errorf("flock index lock: %w", err)
    }
    return f, nil
}
```

**Modify `appendIndex`** to use `lockIndex` instead of flocking index.jsonl directly:
```go
func (s *Store) appendIndex(rec SessionRecord) error {
    data, err := json.Marshal(rec)
    if err != nil {
        return fmt.Errorf("marshal session record: %w", err)
    }
    data = append(data, n)

    // Acquire advisory lock via index.lock (not on index.jsonl itself,
    // because compactIndex may rename over the data file).
    lf, err := s.lockIndex()
    if err != nil {
        return err
    }
    defer func() {
        _ = lockfile.FlockUnlock(lf)
        _ = lf.Close()
    }()

    indexPath := filepath.Join(s.dir, "index.jsonl")
    f, err := os.OpenFile(indexPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
    if err != nil {
        return fmt.Errorf("open index file: %w", err)
    }
    defer func() { _ = f.Close() }()

    if _, err := f.Write(data); err != nil {
        return fmt.Errorf("write index entry: %w", err)
    }
    return nil
}
```

Key change: `appendIndex` no longer flocks `index.jsonl` directly. Instead it acquires `index.lock`, then opens `index.jsonl` with O_APPEND. Since the open happens AFTER acquiring the lock, it always opens the current file at that path (even if compactIndex just renamed a new file into place).

### internal/sessions/purge.go (add `compactIndex`, call from `PurgeOlderThan`)

**Add `compactIndex` method** to Store:
```go
// compactIndex rewrites index.jsonl, removing entries whose session
// directories no longer exist on disk. Uses index.lock for coordination
// with concurrent appendIndex callers.
func (s *Store) compactIndex() error {
    lf, err := s.lockIndex()
    if err != nil {
        return err
    }
    defer func() {
        _ = lockfile.FlockUnlock(lf)
        _ = lf.Close()
    }()

    indexPath := filepath.Join(s.dir, "index.jsonl")

    data, err := os.ReadFile(indexPath)
    if err != nil {
        if os.IsNotExist(err) {
            return nil // nothing to compact
        }
        return fmt.Errorf("read index: %w", err)
    }

    // Parse and filter: keep entries whose session directory exists.
    var surviving []byte
    scanner := bufio.NewScanner(bytes.NewReader(data))
    scanner.Buffer(make([]byte, 0, 64*1024), 1*1024*1024)
    lineNum := 0
    for scanner.Scan() {
        lineNum++
        line := scanner.Bytes()
        if len(line) == 0 {
            continue
        }
        var rec SessionRecord
        if err := json.Unmarshal(line, &rec); err != nil {
            log.Printf("[sessions] compactIndex: skipping corrupt line %d: %v", lineNum, err)
            continue // drop corrupt lines during compaction
        }
        sessDir := filepath.Join(s.dir, rec.SessionID)
        if _, err := os.Stat(sessDir); err != nil {
            if os.IsNotExist(err) {
                continue // session directory was purged
            }
            // For non-NotExist stat errors (permissions, etc.),
            // keep the entry to avoid silent data loss.
            log.Printf("[sessions] compactIndex: stat %s: %v (keeping entry)", rec.SessionID, err)
        }
        surviving = append(surviving, line...)
        surviving = append(surviving, n)
    }
    if err := scanner.Err(); err != nil {
        return fmt.Errorf("scan index: %w", err)
    }

    // Atomic write: temp file + rename.
    tmpPath := indexPath + ".tmp"
    if err := os.WriteFile(tmpPath, surviving, 0o644); err != nil {
        return fmt.Errorf("write index tmp: %w", err)
    }
    if err := os.Rename(tmpPath, indexPath); err != nil {
        _ = os.Remove(tmpPath)
        return fmt.Errorf("rename index: %w", err)
    }

    return nil
}
```

**Modify `PurgeOlderThan`** to call `compactIndex` after removing directories:
```go
func (s *Store) PurgeOlderThan(age time.Duration) (int, error) {
    cutoff := time.Now().UTC().Add(-age)

    records, err := s.Query(Filter{})
    if err != nil {
        return 0, fmt.Errorf("query index: %w", err)
    }

    purged := 0
    for _, rec := range records {
        if rec.Status == StatusRunning {
            continue
        }
        if rec.EndedAt == nil {
            continue
        }
        if rec.EndedAt.Before(cutoff) {
            sessDir := filepath.Join(s.dir, rec.SessionID)
            if err := os.RemoveAll(sessDir); err != nil {
                return purged, fmt.Errorf("remove session %s: %w", rec.SessionID, err)
            }
            purged++
        }
    }

    // Compact index to remove entries for purged session directories.
    if purged > 0 {
        if err := s.compactIndex(); err != nil {
            return purged, fmt.Errorf("compact index: %w", err)
        }
    }

    return purged, nil
}
```

