func buildPRTitle(dir, sourceBranch, targetBranch string) string {
    // Use first commit message subject as title
    output, err := RunGitCommand(dir, "log", fmt.Sprintf("%s..origin/%s", targetBranch, sourceBranch), "--oneline", "--reverse")
    if err != nil || strings.TrimSpace(output) == "" {
        // Fallback: use branch name
        return fmt.Sprintf("Merge %s into %s", sourceBranch, targetBranch)
    }
    lines := strings.Split(strings.TrimSpace(output), "\n")
    if len(lines) == 1 {
        // Single commit: use its message as title (strip hash)
        parts := strings.SplitN(lines[0], " ", 2)
        if len(parts) == 2 {
            return parts[1]
        }
    }
    // Multiple commits: use branch name as title
    return fmt.Sprintf("Merge %s into %s", sourceBranch, targetBranch)
}
```

