package webui

import (
    "context"
    "fmt"
    "log/slog"
    "net/http"
    "net/url"
    "time"

    "github.com/tysonthomas9/loomcli/internal/webui/oauth"
    "github.com/tysonthomas9/loomcli/internal/webui/userstore"
)

// handleOAuthLogin returns a handler that initiates the OAuth authorization flow.
// It generates a CSRF state token and redirects the browser to the provider's
// authorization URL.
func handleOAuthLogin(provider oauth.Provider, stateStore *oauth.StateStore) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        state, err := stateStore.Generate()
        if err != nil {
            respondError(w, http.StatusInternalServerError, "failed to generate state")
            return
        }
        http.Redirect(w, r, provider.AuthURL(state), http.StatusFound)
    }
}

// handleOAuthCallback returns a handler that processes the OAuth provider's callback.
// It validates the CSRF state, exchanges the authorization code for a token,
// fetches the user profile, upserts the user, and issues a session cookie.
func handleOAuthCallback(provider oauth.Provider, stateStore *oauth.StateStore, users *userstore.Store, sessionKey []byte, sessionExpiry time.Duration, secureCookies bool, logger *slog.Logger) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        // authError redirects to the SPA with an error query param
        authError := func(reason string) {
            target := "/?auth_error=" + url.QueryEscape(reason)
            http.Redirect(w, r, target, http.StatusFound)
        }

        // Validate CSRF state
        state := r.URL.Query().Get("state")
        if state == "" || !stateStore.Validate(state) {
            logger.Warn("OAuth callback: invalid state", "state_present", state != "")
            authError("state_invalid")
            return
        }

        // Check for error from provider (e.g., user denied access)
        if errParam := r.URL.Query().Get("error"); errParam != "" {
            logger.Warn("OAuth callback: provider error", "error", errParam)
            authError("provider_denied")
            return
        }

        ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
        defer cancel()

        // Exchange code for access token
        code := r.URL.Query().Get("code")
        if code == "" {
            authError("exchange_failed")
            return
        }
        accessToken, err := provider.ExchangeCode(ctx, code)
        if err != nil {
            logger.Error("OAuth callback: code exchange failed", "error", err)
            authError("exchange_failed")
            return
        }

        // Fetch user profile from provider
        userInfo, err := provider.FetchUser(ctx, accessToken)
        if err != nil {
            logger.Error("OAuth callback: fetch user failed", "error", err)
            authError("fetch_failed")
            return
        }

        // Determine role for new users (first user gets admin)
        count, err := users.CountUsers(ctx)
        if err != nil {
            logger.Error("OAuth callback: count users failed", "error", err)
            authError("store_error")
            return
        }
        newUserRole := userstore.RoleMember
        if count == 0 {
            newUserRole = userstore.RoleAdmin
        }

        // Upsert user — creates on first login, updates profile on subsequent logins
        // UpsertByGitHubID preserves existing role for returning users
        // For new users, the role from the User struct is used
        dbUser, err := users.UpsertByGitHubID(ctx, &userstore.User{
            GitHubID:    userInfo.GitHubID,
            GitHubLogin: userInfo.Login,
            Email:       userInfo.Email,
            AvatarURL:   userInfo.AvatarURL,
            Name:        userInfo.Name,
            Role:        newUserRole,
        })
        if err != nil {
            logger.Error("OAuth callback: upsert user failed", "error", err)
            authError("store_error")
            return
        }

        // Generate session JWT
        token, err := GenerateSessionToken(
            dbUser.ID, dbUser.GitHubLogin, string(dbUser.Role),
            sessionKey, sessionExpiry,
        )
        if err != nil {
            logger.Error("OAuth callback: generate token failed", "error", err)
            authError("token_error")
            return
        }

        // Set session cookie and redirect to SPA
        SetSessionCookie(w, token, sessionExpiry, secureCookies)
        logger.Info("OAuth login successful",
            "user_id", dbUser.ID,
            "login", dbUser.GitHubLogin,
            "role", dbUser.Role,
        )
        http.Redirect(w, r, "/", http.StatusFound)
    }
}

// handleOAuthLogout returns a handler that clears the session cookie.
func handleOAuthLogout(secureCookies bool) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        ClearSessionCookie(w, secureCookies)
        respondJSON(w, http.StatusOK, map[string]bool{"success": true})
    }
}

// AuthMeResponse is the response body for GET /api/auth/me.
type AuthMeResponse struct {
    AuthMethod string         `json:"auth_method"`
    User       *AuthMeUser    `json:"user"`
}

// AuthMeUser is the user portion of the /api/auth/me response.
type AuthMeUser struct {
    ID          string `json:"id"`
    GitHubLogin string `json:"github_login"`
    Name        string `json:"name"`
    Email       string `json:"email"`
    AvatarURL   string `json:"avatar_url"`
    Role        string `json:"role"`
}

// handleAuthMe returns a handler that reports the authenticated user's identity.
// For API-key auth, returns auth_method without user details.
// For session auth, looks up the full user profile from the store.
func handleAuthMe(users *userstore.Store, sessionKey []byte) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        actor, ok := ActorFromContext(r.Context())
        if !ok || actor == nil {
            respondError(w, http.StatusUnauthorized, "authentication required")
            return
        }

        if actor.IsAPIKey() {
            respondJSON(w, http.StatusOK, AuthMeResponse{
                AuthMethod: string(AuthMethodAPIKey),
                User:       nil,
            })
            return
        }

        // Session auth — look up full user profile
        ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
        defer cancel()

        user, err := users.GetUserByID(ctx, actor.UserID)
        if err != nil {
            respondError(w, http.StatusInternalServerError, "failed to fetch user")
            return
        }
        if user == nil {
            // User was deleted after JWT was issued — clear stale cookie
            ClearSessionCookie(w, r.TLS != nil)
            respondError(w, http.StatusUnauthorized, "user not found")
            return
        }

        respondJSON(w, http.StatusOK, AuthMeResponse{
            AuthMethod: string(AuthMethodSession),
            User: &AuthMeUser{
                ID:          user.ID,
                GitHubLogin: user.GitHubLogin,
                Name:        user.Name,
                Email:       user.Email,
                AvatarURL:   user.AvatarURL,
                Role:        string(user.Role),
            },
        })
    }
}
```

