### Mock Setup Pattern

Each test follows this pattern:

```typescript
test('approve flow', async ({ page, mockApi, mockSSE }) => {
  // 1. Track approve state for dynamic ready response
  let approved = false;

  // 2. Mock /api/ready with dynamic response
  await page.route('**/api/ready', async (route) => {
    const issues = approved
      ? [reviewIssue2] // issue1 moved to open, no longer in review
      : [reviewIssue1, reviewIssue2];
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ success: true, data: issues }),
    });
  });

  // 3. Mock issue detail endpoint
  await mockApi.mockIssue('review-plan-001', reviewDetails1);
  await mockApi.mockAuth();

  // 4. Mock PATCH /api/issues/:id with request body capture
  const patchCalls = [];
  await page.route('**/api/issues/review-plan-001', async (route) => {
    if (route.request().method() === 'PATCH') {
      patchCalls.push(route.request().postDataJSON());
      approved = true;
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ success: true, data: { ...reviewIssue1, status: 'open' } }),
      });
    } else {
      await route.fallback();
    }
  });

  // 5. SSE setup
  await mockSSE.connect();
  await page.goto('/');
  await page.waitForLoadState('domcontentloaded');
  mockSSE.sendConnected();

  // ... test steps
});
```

