### `internal/webui/frontend/src/hooks/useWebhooks.ts`

React hook for webhook state management:

**Return type:**

```typescript
export interface UseWebhooksReturn {
  /** Current webhook list, null if not loaded */
  webhooks: WebhookView[] | null;
  /** Whether the initial fetch is in progress */
  isLoading: boolean;
  /** Error message from the last operation */
  error: string | null;
  /** Whether a mutation (create/update/delete) is in progress */
  isSaving: boolean;
  /** Create a new webhook. Returns the full response including the one-time secret. */
  createWebhook: (req: CreateWebhookRequest) => Promise<WebhookCreateResponse | null>;
  /** Update a webhook by ID. Returns true on success. */
  updateWebhook: (id: string, req: UpdateWebhookRequest) => Promise<boolean>;
  /** Delete a webhook by ID. Returns true on success. */
  deleteWebhook: (id: string) => Promise<boolean>;
  /** Send a test event to a webhook. Returns the delivery log entry. */
  testWebhook: (id: string) => Promise<DeliveryLogEntry | null>;
  /** Whether a test delivery is in progress */
  isTesting: boolean;
  /** Re-fetch webhooks from the API */
  refetch: () => void;
}
```

**Implementation structure (mirrors useBackendConfig):**

```typescript
export function useWebhooks(): UseWebhooksReturn {
  const [webhooks, setWebhooks] = useState<WebhookView[] | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isTesting, setIsTesting] = useState(false);

  const mountedRef = useRef(true);
  const webhooksRef = useRef(webhooks);
  webhooksRef.current = webhooks;

  // Mounted guard effect (same as useBackendConfig)
  useEffect(() => { mountedRef.current = true; return () => { mountedRef.current = false; }; }, []);

  // fetchWebhooks — GET /api/webhooks, set state
  const fetchWebhooks = useCallback(async () => { ... }, []);

  // Fetch on mount
  useEffect(() => { fetchWebhooks(); }, [fetchWebhooks]);

  // createWebhook — optimistic add with temp ID, then replace on success or remove on failure
  const create = useCallback(async (req) => {
    const tempId = `temp-${Date.now()}`;
    const tempView: WebhookView = { id: tempId, name: req.name, url: req.url, ... };
    const previous = webhooksRef.current;
    setWebhooks(prev => prev ? [...prev, tempView] : [tempView]);
    setIsSaving(true); setError(null);
    try {
      const result = await api.createWebhook(req);
      if (mountedRef.current) {
        // Replace temp entry with server response (strip secret for the stored view)
        setWebhooks(prev => prev ? prev.map(w => w.id === tempId ? { ...result, secret: undefined } as WebhookView : w) : prev);
      }
      return result;
    } catch {
      if (mountedRef.current) { setWebhooks(previous); setError(...); }
      return null;
    } finally {
      if (mountedRef.current) setIsSaving(false);
    }
  }, []);

  // updateWebhook — optimistic merge, rollback on failure
  const update = useCallback(async (id, req) => {
    const previous = webhooksRef.current;
    setWebhooks(prev => prev ? prev.map(w => w.id === id ? { ...w, ...req } : w) : prev);
    setIsSaving(true); setError(null);
    try {
      const result = await api.updateWebhook(id, req);
      if (mountedRef.current) setWebhooks(prev => prev ? prev.map(w => w.id === id ? result : w) : prev);
      return true;
    } catch {
      if (mountedRef.current) { setWebhooks(previous); setError(...); }
      return false;
    } finally {
      if (mountedRef.current) setIsSaving(false);
    }
  }, []);

  // deleteWebhook — optimistic removal, restore on failure
  const remove = useCallback(async (id) => {
    const previous = webhooksRef.current;
    setWebhooks(prev => prev ? prev.filter(w => w.id !== id) : prev);
    setIsSaving(true); setError(null);
    try {
      await api.deleteWebhook(id);
      return true;
    } catch {
      if (mountedRef.current) { setWebhooks(previous); setError(...); }
      return false;
    } finally {
      if (mountedRef.current) setIsSaving(false);
    }
  }, []);

  // testWebhook — no optimistic state, just loading
  const test = useCallback(async (id) => {
    setIsTesting(true); setError(null);
    try {
      const entry = await api.testWebhook(id);
      return entry;
    } catch {
      if (mountedRef.current) setError(...);
      return null;
    } finally {
      if (mountedRef.current) setIsTesting(false);
    }
  }, []);

  return { webhooks, isLoading, error, isSaving, createWebhook: create, updateWebhook: update, deleteWebhook: remove, testWebhook: test, isTesting, refetch: fetchWebhooks };
}
```

